from book import Chapter
c=Chapter('11')
c.src('R55084',0,start='提出这个想法的初衷',end='复杂的程序应用就无法构造出来。',replacements=[('提出这个想法的初衷是','我的出发点，是'),('其实我正想再后面提到更深的一个想法，就是','更进一步，我希望'),('任何一个领域','在一个领域中'),('都会导致构造复杂度的增加而变得不可持续','都可能随着组合规模增大而放大解释负担'),('试想没有完善的乐谱记谱体系，仅靠人类早期记录音乐的方式，无法构造复杂的交响乐','试想，复杂交响乐的创作与协作，如果没有足够清楚的记谱方式，要让不同演奏者反复准确重现，就会困难得多')])
c.add('''乐谱并不替代听觉经验，它让一部分关系能够被稳定表达：什么时间，由什么乐器，演奏怎样的音与节奏。演奏仍然需要人的理解和训练，但不必在每次排练时从一句模糊描述重新猜起。

我对智能系统内部语言的设想，也从这种关系出发。人可以继续用自然语言表达目的，机器内部已经明确的对象、条件与操作，则不必在每个环节都重新变回一段需要解释的文字。''')
c.heading('让自然语言成为丰富的入口，让内部关系保持明确')
c.src('R55370',0,end='反复的在二进制数据和代码与自然语言的表示之间互相转换。',replacements=[('我最近的两个开发路线','我安排的两个研究方向'),('如何打造更合理的FPM模型','怎样用于构造更合适的 FPM 模型'),('不再是整个体系的核心了','不必继续承担整个体系的全部内部表示'),('自然语言只作为人机交互界面','自然语言可以主要作为人机交互界面'),('而不是作为中间结果','减少把它作为中间结果时'),('反复的在','反复地在')])
c.add('''例如，一个任务已经得到“需要读取的文件、操作的版本、参数的类型、允许写入的位置”这些明确对象，下一步就可以把这些关系交给相应组件，而不必先生成一段叙述，再让另一个模型从叙述里猜回同样的对象。

这并不是要求消灭文字。解释理由、提出开放问题、理解人的含混意图，仍然需要丰富的语言能力。要减少的是那些已经确定、却在重复解释中重新变得不确定的环节。''')
c.heading('内容标识，怎样参与语言与依赖结构')
c.src('R54803',0,replacements=[('newlanguage的merkle-DAG框架下，如果这种语言','在 newlanguage 的 Merkle-DAG 框架设想中，如果一种语言'),('所有的类型名，函数名和数据变量标识符等','类型、函数和数据对象的相关标识'),('就会被简化为基于hashtable的key-value查表操作，速度会大幅提升，操作会大幅简化，这个构想对吗？','其中一部分名称解析与依赖定位工作，能否转化为对内容标识及其关系的查询？这种变化究竟能简化多少操作，需要具体研究。')])
c.add('''把对象的身份写清楚，是一个起点。它可以帮助不同文件和项目指向同一份内容，却不会自动完成类型检查、程序执行和语义证明。同一个功能的不同实现，也不应该因为功能相近就拥有相同的内容标识。

因此，需要分开功能约定和具体实现。功能约定说明输入、输出与适用条件；实现说明怎样完成它。多个实现可以指向同一份约定，再通过相应验证说明哪些条件下可以替换。原始代码字节相同，是内容问题；行为在某些条件下相同，是另外需要证明或检验的问题。''')
c.heading('哈希值之间的距离，不是意义之间的距离')
c.src('R48623',0,start='极大概率会出现hash token爆炸',end='更精确的语义空间距离定义。',replacements=[('极大概率会出现hash token爆炸，而且会有语义空间中相近的对象，在hash token的数值空间中距离太大的问题，而方案C虽然可以能解决这些问题，又会导致整个项目的复杂度、工作量和运算量过于巨大的问题','把每个内容哈希直接当作一个独立 token，可能导致数量迅速增长；而语义相近的对象，其哈希数值也未必接近。另一端，如果试图一次构造过于复杂的语义系统，又可能使工作量与计算量过大'),('前者代码构造简单，但是运行结果不理想，后者运行结果理想，但是代码构造过程复杂。都不是一个前期验证想法的实验软件项目的理想方案。','如何在构造成本和表示能力之间选择，需要一个能够逐步检验的方案。'),('但是我觉得这个问题可以在这个项目中，引入','我想到，可以引入'),('比如硬件平台空间名','比如硬件平台名字空间'),('操作系统空间名','操作系统名字空间'),('这样我们可以','\n\n这样我们可以'),('建立更约束的，更精确的语义空间距离定义','研究受结构和上下文约束的语义关系，而不直接使用哈希的数值距离')])
c.add('''这种自上而下与自下而上的结合，可以用一个工具箱来理解。螺丝刀、扳手和测量仪器各有具体结构，但它们也可以按用途、尺寸和适用环境分类。分类不是把工具的内部构造删掉，而是帮助我们在需要时缩小寻找范围。

同样，一个语义节点可以由更小节点组成，也可以同时属于某个领域、平台和任务范围。这些关系提供了结构信息。模型是否能够利用它们，要通过实际任务来判断，而不是把一个很长的哈希字符串换进词表，就算已经理解了结构。''')
c.heading('Structoken：结构可能保存在哪里')
c.add('''Structoken 的研究问题，是让结构化对象怎样进入模型的表示与计算。一个程序图里至少有几类不同关系：哪些节点依赖哪些节点，一个操作怎样由部件组合，以及同一节点在不同上下文中怎样发挥作用。把它们全部压成向量空间中的远近，可能会遗漏重要区别。

已归档的阶段材料提出过一个值得继续检验的观察：某些静态表示上的探测较弱，而运行中的层更新或局部计算，对图中的真实邻接关系更敏感。它提示我们，结构不一定只保存在“一个节点对应一个点”的位置里，也可能体现在计算怎样沿着关系流动。这里讨论的是阶段材料提出的线索，尚不能据此宣布已经找到了所有模型处理结构的统一机制。''',reason='依据项目假设框架与历史讨论概述；研究材料不是作者原话，未将阶段结论扩大为通用证明')
c.add('''这个区别会直接影响实验。若只检查最后一层的某个向量能否读出图距离，结果不好，可能是模型没有学到结构，也可能是选错了读取位置和方式。要区分这两种解释，就需要改变图关系、改变上下文，并观察相关计算是否随之变化。一个能区分解释的实验，比反复调参直到出现想看的图形更有价值。''')
c.heading('不确定性也可以有类型和内部结构')
c.src('R55180',0,start='这种不确定性，确实是有类型的',end='你觉得这个想法可行吗？',replacements=[('任何复杂对象的不确定性，都可以通过这个对象 的复合结构中子对象的不确定性，复合估算出来的','一些复杂对象的不确定性，可以通过其组成部分及相互依赖来分析和估计'),('这一点与之前提到的通过merkle-DAG框架估算程序的benchmark/profiling一样','这使我想到程序性能测量中的分层分析'),('其不确定性也可以通过记录这些节点的不确定性，来估算这些节点组合形成复杂结构时的不确定性的概率区间','记录节点及其依赖条件之后，可以尝试估计组合结构中的不确定性范围'),('目前的计算机软件生态，在处理对象时，基本上处于两个极端的区间','实际工具的使用中，常常能看见两个相隔很远的处理方向'),('其实jev尝试的就是这部分区间','这部分中间区间，同样值得专门设计处理方式'),('而我在最近的fpm-research-lab中，尝试','在 FPM 的研究中，我希望尝试'),('之前的benchmark/profiling','性能测量与运行分析'),('toekn','token'),('你觉得这个想法可行吗？','这是需要逐步检验的方案。'),('而有了这些数据之后','\n\n而有了这些数据之后'),('问题是，很多问题','\n\n问题是，很多问题')])
c.add('''例如，一个任务的不确定性可能来自缺少某个参数，另一个任务则可能存在几种互相竞争的解释。前者可以请求补充或查询，后者可能需要比较证据。若把它们全部当成同一种模糊文字问题，就很难选择合适的处理成本。

组合估计也需要知道依赖关系。两个步骤若共享同一份可能出错的资料，它们的错误并不独立；不能把每个节点单独测出的概率随意相乘。类型和结构的作用，是把这类条件显露出来，而不是使不确定性凭空消失。''')
c.heading('FPM 与认知前端：共同结构和个体表达怎样分工')
c.src('R55084',0,start='而现在的大模型LLM中',end='认知前端LLM。',replacements=[('而现在的大模型LLM中','在以自然语言为主要材料的大模型中'),('占用宝贵的内存资源，而不是靠外部的知识数据库查询','这使我思考，哪些知识适合保存在模型中，哪些适合通过外部知识库访问'),('我有一个想法不知道是否可行，因为','我提出一个值得尝试的方向：在'),('反向计算获得LLM内部知识的分层以及所属领域等信息','研究能否推断模型内部知识的层级与领域关系'),('所以从长远来看，我支持你11节提出的想法','从长远来看，我希望'),('具有标准语义的通用人工智能模型FPM','以明确语义结构为基础的 FPM 模型')])
c.add('''这里的 K0、K1、K∞，分别用来设想基础词汇、常用构造与按需展开的更广泛知识。它们首先是一种分层思路，而不是已经找到的唯一最优边界。哪些结构应该内置，哪些适合检索或组合，需要结合任务、频率与实际成本来决定。

在这一设想中，认知前端可以适应不同人的语言、专业背景和表达习惯，内部共同结构则尽量保持清楚。这样，个性化不必把公共知识重新切碎，公共基础也不必强迫所有人使用同一种表面语言。''')
c.src('R55469',0,start='但是这个框架还没有渗透到模型训练的内部',replacements=[('但是这个框架还没有渗透到模型训练的内部','这个方向还需要进入模型训练的内部'),('现在的各家大模型就是一个各自独自存在的巨大的数据代码孤岛，其中间结果的巨大利用价值都被封装在这些孤岛里，无法释放','不同模型的训练与内部表示，往往仍然各自独立，许多中间成果难以被其他研究直接使用'),('不知道你对此有何看法，如何','怎样'),('让一个优秀的迭代进化特性，可以快速的应用到其他模型中去','让一项经过检验的改进，有机会被其他模型继续采用？')])
c.add('''共享训练材料、结构定义、实验过程和适用条件，可以先于任意模型参数的直接互换而发生。不同模型内部坐标与训练方式不同，一份有效表示能否迁移，仍然要经过验证。把这个问题逐层展开，才可能让模型也进入共同知识与持续构造的生态。

语言、模型与可复用能力并不是三件孤立的产品。它们分别处理怎样表达，怎样探索，以及怎样保存能够再次使用的结果。要让它们进入个人生活与现实设备，还需要一个能够连接现有软件和资源、逐步生长的运行框架。''')
c.save({'reasoning':'乐谱类比→输入输出与内部表示→语义约定与实现→哈希距离问题→多层结构表示→类型化不确定性→FPM与前端→模型间知识共享','examples':['乐谱','文件参数的结构化传递','工具箱分类','图关系干预','缺参数与竞争解释','共享资料导致相关误差'],'objections':['哈希词表等于理解吗','CID相同等于语义相同吗','静态探测失败能否证明无结构','节点误差能否直接相乘','模型内部表示能否直接互换'],'evidence_refs':['STRUCTOKEN','R54935'],'voice':'大部分沿作者语义分层、命名空间、不确定性和FPM原话展开；项目材料不计作作者原话','status':'初校；拟议内部结构与已验证实验严格分开'})
